#!/usr/bin/env python3
# Generates src/font_data.c: an 8x16 anti-aliased ASCII (32..126) bitmap font
# atlas for suxty's own-drawn UI.  Rasterised from DejaVu Sans Mono Bold
# (Bitstream Vera licence: free to embed/redistribute, the glyph shapes are
# only used as bitmap data here).  Run once; the generated file is checked in,
# so the build does not depend on Python or PIL.
#
# usage: tools/gen_font.py [path/to/DejaVuSansMono-Bold.ttf] > src/font_data.c
import sys
from PIL import Image, ImageDraw, ImageFont

ttf = sys.argv[1] if len(sys.argv) > 1 else "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf"
CW, CH = 8, 16
COLS, ROWS = 16, 8                  # atlas = 128 x 128 (cells 0..15 per row)
SIZE = 13
font = ImageFont.truetype(ttf, SIZE)
atlas = Image.new("L", (CW * COLS, CH * ROWS), 0)
asc, desc = font.getmetrics()
for code in range(32, 127):
    cell = Image.new("L", (CW * 4, CH * 4), 0)       # supersample to get decent AA at tiny size
    big = ImageFont.truetype(ttf, SIZE * 4)
    d = ImageDraw.Draw(cell)
    w = d.textlength(chr(code), font=big)
    d.text(((CW * 4 - w) / 2, (CH * 4 - (asc + desc) * 4) / 2 + 0), chr(code), font=big, fill=255)
    cell = cell.resize((CW, CH), Image.LANCZOS)
    idx = code - 32
    atlas.paste(cell, ((idx % COLS) * CW, (idx // COLS) * CH))
# a solid white texel block in the last cell (used for rectangles)
last = (COLS * ROWS - 1)
atlas.paste(255, ((last % COLS) * CW, (last // COLS) * CH, (last % COLS) * CW + CW, (last // COLS) * CH + CH))
data = atlas.tobytes()
out = []
out.append("/* GENERATED by tools/gen_font.py - do not edit.\n"
           " * 8x16 anti-aliased ASCII font atlas, %dx%d, 8-bit alpha.\n"
           " * Glyph shapes rasterised from DejaVu Sans Mono Bold (Bitstream Vera licence). */\n"
           % (atlas.width, atlas.height))
out.append('#include "font.h"\n')
out.append("const unsigned char font_atlas_alpha[FONT_ATLAS_W * FONT_ATLAS_H] = {")
for i in range(0, len(data), 24):
    out.append("    " + ",".join("%d" % b for b in data[i:i+24]) + ",")
out.append("};")
sys.stdout.write("\n".join(out) + "\n")
atlas.save("/tmp/atlas_preview.png") if len(sys.argv) > 2 else None
